const body = $input.first().json.body || {};
const message = body.message || {};
const type = message.type;

const ALLOWED_FUNCTIONS = ['check_order_status', 'escalate_to_human'];

let responseBody;
let audit;

if (type === 'tool-calls') {
  const toolCalls = message.toolCallList || [];
  const results = [];
  const statuses = [];
  const reasons = [];

  for (const call of toolCalls) {
    const name = (call.function && call.function.name) || call.name;
    const params = (call.function && call.function.arguments) || call.parameters;
    const allowed = ALLOWED_FUNCTIONS.includes(name);
    let resultText;
    let status;
    let reason = null;

    if (!allowed) {
      status = 'blocked';
      reason = `Function "${name}" is not in the allow-list`;
      resultText = "I'm not able to do that directly — let me get a person to help with that.";
    } else if (name === 'escalate_to_human') {
      status = 'escalated';
      resultText = "I've flagged this for a team member to follow up on.";
    } else {
      status = 'success';
      resultText = `Placeholder lookup result for ${name} with params ${JSON.stringify(params)}. Wire this up to a real data source next.`;
    }

    results.push({ toolCallId: call.id, name, result: resultText });
    statuses.push(status);
    if (reason) reasons.push(reason);
  }

  responseBody = { results };
  audit = {
    source: 'phone',
    actor: (message.call && message.call.customer && message.call.customer.number) || (message.call && message.call.id) || 'unknown',
    action: 'tool_calls',
    details: { toolCallList: toolCalls, results },
    status: statuses.includes('blocked') ? 'blocked' : (statuses.includes('escalated') ? 'escalated' : 'success'),
    reason: reasons.join('; ') || null,
  };
} else if (type === 'end-of-call-report') {
  responseBody = {};
  audit = {
    source: 'phone',
    actor: (message.call && message.call.customer && message.call.customer.number) || (message.call && message.call.id) || 'unknown',
    action: 'call_completed',
    details: {
      endedReason: message.endedReason,
      transcript: message.artifact ? message.artifact.transcript : undefined,
    },
    status: 'success',
    reason: null,
  };
} else {
  responseBody = {};
  audit = {
    source: 'phone',
    actor: (message.call && message.call.id) || 'unknown',
    action: type || 'unknown_event',
    details: message,
    status: 'success',
    reason: null,
  };
}

return [{ json: { responseBody, audit } }];
